entries[229376] = { ["name"] = "Prismatische Scheibe des Erzmagiers", ["text"] = "Wirken in 1.5 sek.\nBeschwört Eure prismatische Scheibe des Erzmagiers oder gibt sie wieder frei. Das ist ein Flugreittier.\n\"Drei Elemente wurden verschmolzen, um diese magische Scheibe zu erschaffen, die auf Eure speziellen Zauberkräfte eingestimmt ist.\"\nQuest:\nDie Balance der Scheiben" }
