entries[229387] = { ["name"] = "Giftbrutbezwinger des Todesgebieters", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren Giftbrutbezwinger des Todesgebieters oder gibt ihn wieder frei. Das ist ein Flugreittier.\n\"Ein mächtiger roter Großdrache, der von seiner eigenen Lebensenergie zum Untod erweckt wurde. Wahrhaft eine Verhöhnung des Lebens.\"\nQuest:\nDer Verlorene Gletscher" }
