entries[230384] = { ["name"] = "Zehrender Hunger", ["text"] = "Wirken in 1.5 sek. 5 sek. Abklingzeit\nRuft mehrere Wellenprescher der Reißmäuler herbei, die sich an Spielercharaktere klammern und ihnen alle 2 Sek. 13434 körperlichen Schaden zufügen.\n\nWenn ein Murloc mit ' Donnernder Schock ' getroffen wird, fällt er vom Spielercharakter ab und wird angreifbar." }
