entries[230398] = { ["name"] = "Elfenbeinfarbene Feder", ["text"] = "Wirken in 2 sek.\nVerwandelt Euch in einen Rächer von Aviana. Wenn Ihr in diesem Zustand andere Spielercharaktere tötet, besteht eine Chance, Male der Beute zu erhalten. Kann nur auf Schlachtfeldern und in Ashran verwendet werden.\n(1s Abklingzeit)" }
